```C#
using System;

namespace CalculoPlanck
{
    class Program
    {
        static void Main(string[] args)
        {
            // Convertir longitud de onda de nm a metros
            double wavelength = 600 * Math.Pow(10, -9);

            // Velocidad de la luz (c)
            double c = 299792458;

            // Constante de Planck (h)
            double h = (6.62607004 * Math.Pow(10, -34)) / (wavelength * c);

            // Energía de un fotón con longitud de onda
            double energy = h * c;

            Console.WriteLine("El valor de la constante de Planck (h) es: " + h.ToString("F10") + " J s");
            Console.WriteLine("La energía de un fotón con una longitud de onda de 600 nm es: " + energy.ToString("F10") + " J");
        }
    }
}
```

