4. Paradigma de prueba basado en comportamientos

4.1 Escenarios de comportamiento

Crear un archivo feature con formato Gherkin para documentar los escenarios de comportamiento que cubrirán la prueba.

Ejemplo:

```gherkin
Feature: Account Receivable Invoice Creation

  Scenario: Successfully create invoice with valid data
    Given a Spring Boot application is running
    And the Oracle EBS/EBA system is up and running
    And the following JSON data:
      """
      {
        "customerName": "John Doe",
        "customerAddress": "1234 Main St",
        "invoiceAmount": 100.50,
        "currencyCode": "USD"
      }
      """
    When an HTTP POST request is sent to "/invoices"
    Then HTTP response status code should be 201 CREATED
    And a new invoice with valid data should be created in Oracle EBS/EBA

  Scenario: Fail to create invoice with invalid data
    Given a Spring Boot application is running
    And the Oracle EBS/EBA system is up and running
    And the following JSON data:
      """
      {
        "customerName": "John Doe",
        "invoiceAmount": true,
        "currencyCode": "USD"
      }
      """
    When an HTTP POST request is sent to "/invoices"
    Then HTTP response status code should be 400 BAD REQUEST
    And a validation error message should be included in the response body
```

4.2 Identificadores de comportamiento (specs)

Con cada escenario de comportamiento, crear una clase Java que implemente la interfaz `org.gauge appealed.ApiSpec` en Gauge para especificar la lógica de prueba.

Ejemplo:

```java
import java.util.Random;

import org.gauge appealed.*;
import org.gauge appealed.http.HttpClientMethodSpec;
import org.gauge appealed.http.HttpRequestType;
import org.gauge appealed.spring.stereotype.SpringIntegration;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.web.client.RestTemplate;

@SpringIntegration
public class InvoiceManagementSpec extends HttpClientMethodSpec {

    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private DataFaker<Customer> customerDataFaker;
    private DataFaker<Invoice> invoiceDataFaker;

    @Autowired
    private OracleEbsApi oracleEbsApi;

    // Override(super) methods for Gauge hooks

    @Override
    public String getApiName() {
        return "Invoice Management Service";
    }

    /**
     * Define the HTTP request for creating a new invoice.
     */
    @Override
    public void define(String scenarioName) {
        Random rand = new Random();

        String customerName = customerDataFaker.get().getCustomerName();
        String customerAddress = customerDataFaker.get().getCustomerAddress();
        double invoiceAmount = rand.nextDouble() * 1000 + 1;
        String currencyCode = "USD";

        String requestBody = String.format(
                "{\"customerName\":\"%s\", \"customerAddress\":\"%s\", \"invoiceAmount\":%f, \"currencyCode\":\"%s\"}",
                customerName, customerAddress, invoiceAmount, currencyCode);

        method(HttpRequestType.POST, "/invoices")
                .withRequestData(requestBody)
                .withResponseStatus(HttpStatus.CREATED);
    }

    /**
     * Verify the response status and Oracle EBS/EBA simulation for the creation of a new invoice.
     */
    @Override
    public void verify() {
        // Assert HTTP response status code
        int statusCode = this.getLastResponse().getStatusCodeValue();
        assertEquals(HttpStatus.CREATED.value(), statusCode);

        // Assert Oracle EBS/EBA Simulation
        String invoiceNumber = oracleEbsApi.createInvoice(customerDataFaker.get().getCustomerName(), invoiceAmount);
        assertTrue(oracleEbsApi.verifyInvoiceCreated(invoiceNumber));
    }

    /**
     * Define the HTTP request for invalid invoice creation.
     */
    @Override
    public void defineFailCase(String scenarioName) {
        Random rand = new Random();

        String customerName = "John Doe"; // Valid data
        String customerId = "ABC123"; // Invalid data
        double invoiceAmount = rand.nextDouble() * 1000 + 1;
        String currencyCode = "USD";

        String requestBody = String.format(
                "{\"customerName\":\"%s\", \"customerId\":\"%s\", \"invoiceAmount\":%f, \"currencyCode\":\"%s\"}",
                customerName, customerId, invoiceAmount, currencyCode);

        method(HttpRequestType.POST, "/invoices")
                .withRequestData(requestBody)
                .withResponseStatus(HttpStatus.BAD_REQUEST);
    }

    /**
     * Verify the response status for invalid invoice creation.
     */
    @Override
    public void verifyFailCase() {
        int statusCode = this.getLastResponse().getStatusCodeValue();
        assertEquals(HttpStatus.BAD_REQUEST.value(), statusCode);

        // Assert validation error message...
    }
}
```

