  3.2 Implementación de características y escenarios en Gauge:

    ```java
    // Feature: Crear factura para Invoice Management RESTful API
    // Escenarios:

    feature("Create Invoice") {
      scenario("Success", async () -> {
        // Configuración de índice de datos articulada por DataFaker
        final Invoice invoice = InvoiceDataFactory.createInvoiceData();

        // Configuración del cliente HTTP para la comunicación con la API REST
        RestTemplate restTemplate = new RestTemplate();
        restTemplate.setUriTemplateHandler(new UriTemplateHandler() {
          @Override
          public URI expand(String UriTemplate, Map<String, ?> uriVariables) {
              // Reemplazar con el endpoint real de la API REST del servicio Invoice Management
              return URI.create("http://localhost:8080/api/invoices");
          }
        });

        // Ejecución de petición HTTP POST para crear factura en Oracle EBS
        ResponseEntity<InvoiceResponse> responseEntity = restTemplate.postForEntity("", invoice, InvoiceResponse.class);

        // Validación de resultados utilizando assertJ
        assertThat(responseEntity.getStatusCode()).isEqualTo(HttpStatus.CREATED);
        assertThat(responseEntity.getBody().getinvoiceId()).isNotNull();

        // Validación de datos adicionales en Oracle EBS con assertion específica de Oracle EBS (requisitos específicos)
        // Ejemplo: Acceder a la base de datos Oracle EBS conectándose a través de Spring Boot Data JPA y hacer las validaciones
        // En este ejemplo, Spring Data JPA se instala como dependencia adicional de desarrollo para el proyecto:
        final String DB_URL = System.getenv("DATABASE_URL");
        final String DB_USER = System.getenv("DATABASE_USER");
        final String DB_PASS = System.getenv("DATABASE_PASS");
        final String DB_DRIVER = "oracle.jdbc.driver.OracleDriver";

        PersistenceManager persistenceManager = GaugeContext.persistenceManager();
        EntityManager entityManager = persistenceManager.createEntityManager("invoice-db-jpa");
        entityManager.getEntityManagerFactory().getDataSource().setDriverClassName(DB_DRIVER);

        entityManager
            .unwrap(Session.class)
            .doWork(conn -> {
              try {
                // Ejemplo de conexión para Oracle EBS con JDBC
                Connection connection = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
                Statement statement = connection.createStatement();
                ResultSet resultSet = statement.executeQuery("SELECT invoice_id FROM ar_invoices WHERE invoice_number = '" + invoice.getInvoiceNumber() + "'");
                while (resultSet.next()) {
                  long invoiceId = resultSet.getLong("invoice_id");
                  assertThat(invoiceId).isEqualTo(responseEntity.getBody().getInvoiceId());
                }
              } catch (SQLException e) {
                System.out.println("Error al consultar datos en Oracle EBS: " + e.getMessage());
              }
            });
      });

      scenario("Fail", async () -> {
        // Configuración de índice con datos inválidos
        final Invoice invoice = InvoiceDataFactory.createInvalidInvoiceData();

        // Configuración del cliente HTTP para la comunicación con la API REST
        RestTemplate restTemplate = new RestTemplate();
        restTemplate.setUriTemplateHandler(new UriTemplateHandler() {
          @Override
          public URI expand(String UriTemplate, Map<String, ?> uriVariables) {
              // Reemplazar con el endpoint real de la API REST del servicio Invoice Management
              return URI.create("http://localhost:8080/api/invoices");
          }
        });

        // Ejecución de petición HTTP POST para crear factura en Oracle EBS
        ResponseEntity<InvoiceErrorResponse> responseEntity = restTemplate.postForEntity("", invoice, InvoiceErrorResponse.class);

        // Validación de resultados utilizando assertJ
        assertThat(responseEntity.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
        assertThat(responseEntity.getBody().getErrors().size()).isGreaterThan(0);
      });
    }
    ```

