            categoryFlowers.add(flower);
            CATEGORIES_MAP.put(category, categoryFlowers);
        }
    }

    private static String getCategory(String flower) {
        int categoryIdx = flower.lastIndexOf(" ") + 1; // Obtain the starting index of the last word in the flower name
        String category = getPredefinedCategory(flower.substring(categoryIdx).trim().toUpperCase()); // Extract and capitalize the category name
        return category;
    }

    private static String getPredefinedCategory(String flowerName) {
        for (String predefinedCategory : CATEGORIES) {
