   # Establecer sesión usando las credenciales proporcionadas
   headers = {'Content-Type': 'application/json'}

   authenticator = SSHAuthCodec()
   authenticator.username = username
   authenticator.password = password
   transport_layer = requests.packages.urllib3.util.ssl_.SSLContextWrapper(ssl_version=ssl_.PROTOCOL_TLS)
   transport_layer.wrap_socket(requests.packages.urllib3.PoolManager()._create_connection(requests.packages.urllib3.util.parse_url('https://<hostname>:8443/caswebservice/'), True),
                                context=transport_layer)
   with requests.Session() as session:
       session.auth = SSHAuthCodec(authenticator)
       session.cert = ('<path/to/client.crt>', '<path/to/client.key>')

       try:
           response = session.post('https://<hostname>:8443/caswebservice/authenticate',
                                   headers=headers,
                                   data='{{"Username": "' + username + '", "Password": "' + password + '"}}')
           response.raise_for_status()

           # Tratar el contenido de la respuesta
           api_key_value = response.json()['Value']
           api_key_id = api_key_value['Id']
           api_key_secret = api_key_value['Secret']

           # Reutilizar sesión para otros métodos HTTP con las credenciales para el API key
           headers = {'X-Api-Key': api_key_id + ':' + api_key_secret}
           response = session.get('https://<hostname>:8443/caswebservice/testapi',
                                   headers=headers)

           # Tratar el contenido de la respuesta
           print(response.json())

       except ConnectionError:
           print('Connection Error')
   ```

