\begin{minted}[breaklines]{python}
import tensorflow as tf
import numpy as np
import matplotlib.pyplot as plt

# Definicion del modelo con capas de autoencoder
def autoencoder(n_inputs, n_hidden):
    inputs = tf.keras.layers.Input(shape=(n_inputs,))

    # Capa oculta densa
    h = tf.keras.layers.Dense(n_hidden, activation='relu')(inputs)

    # Capa codificadora lineal
    z = tf.keras.layers.Dense(n_hidden, activation='linear')(h)

    # Capa decodificadora densa
    decoded = tf.keras.layers.Dense(n_inputs, activation='sigmoid')(z)

    # Construccion del modelo autoencoder
    model = tf.keras.models.Model(inputs=inputs, outputs=decoded)

    return model

# Cargar datos de entrenamiento
(x_train, _), (x_test, _) = tf.keras.datasets.mnist.load_data()
x_train = x_train.reshape(x_train.shape[0], 784).astype("float32") / 255
x_test = x_test.reshape(x_test.shape[0], 784).astype("float32") / 255

# Preparando los datos para TensorFlow
train_dataset = tf.data.Dataset.from_tensor_slices(x_train)
train_dataset = train_dataset.shuffle(buffer_size=1024).batch(128)

# Entrenamiento del modelo autoencoder con los datos preparados
vae = autoencoder(784, 512)
vae.compile(optimizer='adam', loss='binary_crossentropy')

history = vae.fit(train_dataset, epochs=20, validation_data=(x_test, x_test))

# Visualizacion del resultado del entrenamiento
plt.plot(history.history['loss'])
plt.plot(history.history['val_loss'])
plt.title('Curva de entrenamiento del autoencoder')
plt.ylabel('Perdida')
plt.xlabel('Época')
plt.legend(['Entrenamiento', 'Validación'], loc='upper right')
plt.show()
\end{minted}

En este ejemplo, utilizamos el marco TensorFlow para construir un modelo de autoencoder con capas densas y lineales, aplicado al reconocimiento de dígitos manuscritos en la base de datos MNIST. Luego, preparamos los datos en batches y entrenamos el modelo durante 20 épocas para luego visualizar la evolución de la pérdida del entrenamiento y validación.

