\label{eq:objective_function_traffic}
& \underset{X}{\text{minímaxizar}} & & f(X) = \sum_{i=1}^n (c_i x_i + d_i y_i) \\
& \text{sujeto a} & & Ax + By \leq b \\
& & & x_i \in \{0,1\} \quad \forall i \in [|N|] \\
& & & y_j \in \{0,1\} \quad \forall j \in [|J|]
\end{aligned}
\end{equation}

 Donde:

