// eslint-disable-next-line no-extra-functionalities

module.exports = {
  rules: {
    // Regla personalizada de estilo para Vue.js
    'vue-state-modifiers': 'error',

    // Definición de la función de evaluación
    'vue/state-modifiers': function (context) {
      return {
        // Definición de un nodo Visitor para chequear method expressions en hooks de ciclo de vida
        MethodExpression(node) {
          const { method } = node;

          // evaluar si el método modifica el estado interno del componente (ejemplo: esta excluyendo métodos como 'updateProps')
          const forbiddenKeywords = ['updateProps'];

          if (
            method.callee.type === 'Identifier' &&
            forbiddenKeywords.includes(method.callee.name) === false &&
            /this\.(state|data|props|computed|watch)$/.test(method.arguments[0].raw)
          ) {
            // Aquí se informa si el método modifica el estado interno del componente
            context.report({
              node,
              message:
                'Hook de ciclo de vida modifica el estado interno del componente: {{methodName}}',
              data: {
                methodName: method.callee.name,
              },
            });

            // Ahora evaluar si el método llama a otro método que modifica el estado interno del componente
            this.walkParentNodes(node, (parent) => {
              if (parent.type === 'MemberExpression') {
                const { object, property } = parent;

                if (property.type === 'Identifier' && object.type === 'ThisExpression') {
                  if (
                    property.name === 'state' ||
                    property.name === 'data' ||
                    property.name === 'props' ||
                    property.name === 'computed' ||
                    property.name === 'watch'
                  ) {
                    const possibleMethodCall = object.type === 'Identifier'
                      ? `${object.name}.${property.name}`
                      : `${object.raw}.${property.name}`;

                    // Aquí se informa si el método llama a otro método que modifica el estado interno del componente
                    context.report({
                      node: parent,
                      message:
                        'El método {{methodName}} llama a otro método que modifica el estado interno del componente: {{possibleMethodCall}}',
                      data: {
                        methodName: method.callee.name,
                        possibleMethodCall,
                      },
                    });
                  }
                }
              }
            });
          }
        },
      };
    },
  },
};
```

